  ('aa5e953c-ae06-46dd-a3cc-94fe136da669', 'c3d6f9b2-7a0e-4c11-8f86-1b5c0d3a2e69', 'e78e029b-3cbd-4eae-b98c-86043edf8ed3', 'subtopic'::public.curated_course_node_type, 'Role of information systems in organizations', 'The point is to see MIS as the bridge between business goals and digital capabilities.', 0),
