  ('4c86fa54-7d2a-45b4-9b7e-2f60305d12cb', 'c3d6f9b2-7a0e-4c11-8f86-1b5c0d3a2e69', '3fd413fa-38f7-4b75-8703-c307cedf4856', 'concept'::public.curated_course_node_type, 'Platform risk, lock-in, and service reliability', null, 2),
