  'Information systems are studied as business capabilities, not just software. Students learn how data, applications, people, processes, and governance create operational performance and strategic advantage, from enterprise systems and analytics through security, architecture, responsible technology, and an implementation roadmap.',
  $misjson${"slug": "management-information-systems", "title": "Management Information Systems", "description": "Information systems are studied as business capabilities, not just software. Students learn how data, applications, people, processes, and governance create operational performance and strategic advantage, from enterprise systems and analytics through security, architecture, responsible technology, and an implementation roadmap.", "topics": [{"id": "e78e029b-3cbd-4eae-b98c-86043edf8ed3", "type": "topic", "title": "MIS Foundations: Business Value, Organizations, and Digital Strategy", "description": "Information systems are studied as business capabilities, not just software. Students learn how data, applications, people, processes, and governance create operational performance and strategic advantage.", "children": [{"id": "aa5e953c-ae06-46dd-a3cc-94fe136da669", "type": "subtopic", "title": "Role of information systems in organizations", "children": [{"id": "ecad0d7b-7d00-47db-b307-befe8211f5f0", "type": "concept", "title": "Operational, managerial, and strategic systems"}, {"id": "2f8768c1-1dd9-4da9-b256-eb34fd8d2aed", "type": "concept", "title": "People, process, technology, and data as a system"}, {"id": "573a193d-5478-4b7f-9982-592549a67809", "type": "concept", "title": "Information systems roles: CIO, product owner, analyst, architect, data steward"}], "description": "The point is to see MIS as the bridge between business goals and digital capabilities."}, {"id": "cb21cae9-e476-409f-b477-abd7adbda5b0", "type": "subtopic", "title": "Business value and competitive advantage", "children": [{"id": "01f002f0-3dba-4a87-a21b-e96d583b9def", "type": "concept", "title": "Strategic alignment and value propositions"}, {"id": "df3f0fc0-a327-4df9-81e2-c896f9ab24e5", "type": "concept", "title": "Network effects, switching costs, and digital scale"}, {"id": "999b5163-b5bf-4c2c-b2de-3e7e0fdead0f", "type": "concept", "title": "Technology-enabled differentiation versus operational efficiency"}], "description": "Students learn how technology creates value only when it changes cost, speed, quality, reach, or decision quality."}, {"id": "a09e3178-74f8-4841-b405-58b5f39bbaea", "type": "subtopic", "title": "Digital business models", "children": [{"id": "8aee430d-0c01-43f5-8039-6a55c8c64335", "type": "concept", "title": "Platforms, ecosystems, subscriptions, marketplaces, and freemium models"}, {"id": "913a8676-0e42-4a57-b5a7-34dfdfdfd3e1", "type": "concept", "title": "E-commerce, omnichannel, and digital customer experience"}, {"id": "ca4e688d-83ba-427b-8837-10a4f7b5e898", "type": "concept", "title": "Data monetization and digital services"}], "description": "This frames MIS as a driver of new markets and revenue models."}]}, {"id": "d631c4ab-90c7-417b-ad0a-f2405f9940c5", "type": "topic", "title": "Business Processes, Systems Thinking, and Process Improvement", "description": "MIS work begins with understanding how organizations actually operate. This topic teaches students to model processes, spot friction, and redesign information flows.", "children": [{"id": "23abc95f-0cd9-4bf2-b5f3-aa9c3ec506f2", "type": "subtopic", "title": "Process mapping", "children": [{"id": "e7dc97df-e754-4e35-b587-829dd2f6e087", "type": "concept", "title": "Swimlane diagrams, value streams, SIPOC, and process boundaries"}, {"id": "65d8be9d-eb43-4a71-af0f-47f65208875c", "type": "concept", "title": "Inputs, outputs, handoffs, exceptions, and controls"}, {"id": "8ebac55e-676f-42a1-b239-0a005423aae3", "type": "concept", "title": "Bottlenecks, rework, queues, and failure points"}], "description": "Students learn to make work visible before trying to automate it."}, {"id": "6044243a-576a-4cb4-9fe8-c25747be8b3c", "type": "subtopic", "title": "Systems thinking", "children": [{"id": "7b982e9b-e3d1-4ca8-b11c-54ac27820eea", "type": "concept", "title": "Stocks, flows, feedback loops, and delays"}, {"id": "67cb88e7-0151-428a-a5d9-8ac02d0bdde2", "type": "concept", "title": "Local optimization versus enterprise outcomes"}, {"id": "c9f42b4d-45f0-4276-926e-8306b4784cdf", "type": "concept", "title": "Process, data, and application dependencies"}], "description": "The gist is understanding feedback, dependencies, and unintended consequences."}, {"id": "acaf8a15-3e5b-4a19-84ac-1e167ba771ff", "type": "subtopic", "title": "Process improvement methods", "children": [{"id": "b337f49e-bc8f-4fea-b83a-dbcbc7ff5f05", "type": "concept", "title": "Lean waste, Six Sigma variation, and root-cause analysis"}, {"id": "82c889c2-5ee3-431e-868a-dc78e0ec1b23", "type": "concept", "title": "Standardization, simplification, and automation readiness"}, {"id": "73633f3f-dfca-44f7-82f2-b08a441af5bc", "type": "concept", "title": "Performance metrics and before-after evaluation"}], "description": "MIS professionals must improve work, not just install software."}]}, {"id": "4d53bd96-9ae8-4a48-9ed3-2bc58cc16b13", "type": "topic", "title": "Data, Databases, SQL Foundations, and Data Governance", "description": "Data is the raw material of modern management. Students learn how data is modeled, stored, queried, protected, and turned into reliable organizational knowledge.", "children": [{"id": "f779ca31-c298-4ef2-b5ff-2f7362dba4d9", "type": "subtopic", "title": "Data modeling and databases", "children": [{"id": "176c7e35-ae9f-4494-933a-513b29ec9fe2", "type": "concept", "title": "Entities, attributes, relationships, keys, and normalization"}, {"id": "8b353da5-618c-4966-8d13-8c5ca7468c5a", "type": "concept", "title": "Relational databases, warehouses, lakes, and lakehouses"}, {"id": "c4ae7476-a1d7-4e32-91cd-4ff6c9691191", "type": "concept", "title": "Structured, semi-structured, and unstructured data"}], "description": "Students learn how business reality becomes structured data."}, {"id": "07b89221-f1dc-4a66-a474-b6ab6b785b31", "type": "subtopic", "title": "SQL and data retrieval", "children": [{"id": "798fdf34-a259-484f-a026-7e7632fc72db", "type": "concept", "title": "SELECT, JOIN, GROUP BY, filters, and aggregation"}, {"id": "3bd6af65-16c3-47bf-b9b1-d2510867ee2f", "type": "concept", "title": "Data quality checks and query interpretation"}, {"id": "2f76333c-5bd4-43ed-817a-0d8d5d516063", "type": "concept", "title": "Views, indexes, permissions, and performance basics"}], "description": "Managers do not need to be database engineers, but they should understand how questions become queries."}, {"id": "34034ada-00a8-4ac1-bb9f-9e7e8b484ced", "type": "subtopic", "title": "Data governance", "children": [{"id": "453a4850-2429-4441-8269-1f4e3a5258af", "type": "concept", "title": "Data ownership, stewardship, lineage, and metadata"}, {"id": "3384aeef-cb87-4752-91cf-348e7d44f6cd", "type": "concept", "title": "Master data management and data catalogs"}, {"id": "0e54cee4-f113-462d-85ef-3ac2d9ee5468", "type": "concept", "title": "Quality, privacy, retention, and access control"}], "description": "Good decisions require trustworthy, accountable data."}]}, {"id": "e1941292-84f5-4881-a243-884b31dc38ff", "type": "topic", "title": "Enterprise Systems: ERP, CRM, SCM, and Integration", "description": "Enterprise systems coordinate work across functions. Students learn why integrated applications are powerful, expensive, risky, and central to large-scale operations.", "children": [{"id": "ea7b6e93-4b4d-405c-82d0-dea74a309758", "type": "subtopic", "title": "ERP modules and enterprise processes", "children": [{"id": "2be98b2e-a8a2-4dbd-8dda-63505c614510", "type": "concept", "title": "Order-to-cash, procure-to-pay, record-to-report, plan-to-produce"}, {"id": "88843355-da61-4ce7-ba00-f56b031d82be", "type": "concept", "title": "Configuration versus customization"}, {"id": "289a4514-d4be-4e68-9e98-0deb09bfd5f8", "type": "concept", "title": "Master data and cross-functional controls"}], "description": "ERP teaches how finance, operations, HR, procurement, and sales connect through shared data."}, {"id": "0630c3ef-c37d-4561-8d90-b2a32ffa69a7", "type": "subtopic", "title": "CRM and customer systems", "children": [{"id": "b6bc00be-a29e-4f27-a622-f3e62d2308d8", "type": "concept", "title": "Lead, opportunity, service, and retention workflows"}, {"id": "4d6f44da-e9f7-455f-a4b3-81869a4649bf", "type": "concept", "title": "Customer data platforms and segmentation"}, {"id": "800cecf0-4938-4aab-82e6-ccc45137f943", "type": "concept", "title": "Customer experience and omnichannel touchpoints"}], "description": "Students learn how firms manage customer relationships across marketing, sales, service, and analytics."}, {"id": "de7c8f6a-56b6-41e4-b227-f1cc27d8d8ee", "type": "subtopic", "title": "SCM and operational integration", "children": [{"id": "ca481ab4-91ed-488a-9c41-c9a878b9dc28", "type": "concept", "title": "Demand planning, MRP, inventory visibility, and fulfillment"}, {"id": "df478162-db45-4f0b-ae82-2bdf4abb41e4", "type": "concept", "title": "Supplier portals and EDI/API integration"}, {"id": "a14765d0-4138-413b-81f6-95e666810edf", "type": "concept", "title": "Traceability, resilience, and risk monitoring"}], "description": "Supply-chain systems show how information coordinates inventory, logistics, suppliers, and demand."}]}, {"id": "fc74ccc8-4ecb-4576-8fa1-0fbcaeb24abd", "type": "topic", "title": "Business Intelligence, Analytics, Dashboards, and Decision Support", "description": "MIS turns data into decisions. This topic develops the reporting, visualization, metric design, and analytical reasoning needed for managers to act on evidence.", "children": [{"id": "e0fc2f83-cc20-4d3b-a731-7256b9912b9d", "type": "subtopic", "title": "BI foundations", "children": [{"id": "cd40cfab-beee-48c6-a0a2-987b4fe9f21e", "type": "concept", "title": "ETL/ELT pipelines, warehouses, semantic layers, and cubes"}, {"id": "c75bc789-b69a-492b-85cc-c5bb40549f2e", "type": "concept", "title": "Operational, tactical, and strategic reporting"}, {"id": "e39aed11-42e3-4814-b5ae-6ba35954dc9c", "type": "concept", "title": "Self-service BI and governed analytics"}], "description": "Students learn how reporting systems summarize operations for managerial attention."}, {"id": "213eb931-47c5-4746-9252-c5f88ca6fbd2", "type": "subtopic", "title": "Dashboard design", "children": [{"id": "39132c9a-9bdf-4529-bd2b-127494e67b97", "type": "concept", "title": "KPIs, leading and lagging indicators, targets, and thresholds"}, {"id": "2df1b365-8412-4381-9726-0aad42e9f330", "type": "concept", "title": "Visual perception, chart selection, and narrative context"}, {"id": "939fb726-5884-42f4-b316-99cd71bac392", "type": "concept", "title": "Drilldowns, filters, alerts, and executive views"}], "description": "The aim is to communicate what matters without hiding assumptions."}, {"id": "086d910c-d960-4caf-a47f-1c71d36e6e05", "type": "subtopic", "title": "Decision support", "children": [{"id": "f7db0e4c-5e65-4b70-80ea-2146e1f2fb06", "type": "concept", "title": "What happened, why it happened, what may happen, and what to do next"}, {"id": "96aa9233-f466-4afa-9643-9590789e1067", "type": "concept", "title": "Scenario analysis, simulation, and optimization awareness"}, {"id": "b60da4ce-0d6a-4c99-8752-6d62f3be527c", "type": "concept", "title": "Decision rights, accountability, and metric gaming"}], "description": "MIS connects descriptive analytics to action."}]}, {"id": "de3c0ff9-f005-40d4-b011-2969b5de100b", "type": "topic", "title": "IT Infrastructure, Cloud Computing, and Enterprise Platforms", "description": "Every business system runs on infrastructure choices. Students learn enough about hardware, software, cloud, storage, and platforms to make sound managerial decisions.", "children": [{"id": "bf828cbc-db7c-49ab-865a-44d993ebcc3d", "type": "subtopic", "title": "Computing fundamentals", "children": [{"id": "5377d096-c448-46e4-a43e-56bc2c1be3f2", "type": "concept", "title": "Servers, endpoints, storage, operating systems, virtualization"}, {"id": "03a8ea18-0ae1-4a88-af6a-0af32b7b11ad", "type": "concept", "title": "Availability, scalability, latency, backup, and recovery"}, {"id": "43956d2c-74f8-48d4-86a0-79b59de3bfc5", "type": "concept", "title": "Total cost of ownership and lifecycle management"}], "description": "Students build enough technical literacy to evaluate infrastructure tradeoffs."}, {"id": "316d9d0f-32b5-473e-a95b-153fb337002e", "type": "subtopic", "title": "Cloud models", "children": [{"id": "a2e6185c-77b9-4fad-a0cc-af93a6fab8f1", "type": "concept", "title": "IaaS, PaaS, SaaS, serverless, public, private, hybrid, and multicloud"}, {"id": "28f5705c-38d9-420a-8af2-25be86925a19", "type": "concept", "title": "Elasticity, managed services, regions, and shared responsibility"}, {"id": "53f7f596-03ad-4d7f-8f18-f127936e26e2", "type": "concept", "title": "Cloud economics, FinOps, and migration patterns"}], "description": "Cloud is a sourcing and architecture decision, not just a hosting option."}, {"id": "3fd413fa-38f7-4b75-8703-c307cedf4856", "type": "subtopic", "title": "Enterprise platforms", "children": [{"id": "6ff7f22e-3d6b-41ed-910a-388ee599711c", "type": "concept", "title": "Identity platforms, collaboration suites, data platforms, low-code platforms"}, {"id": "a3b33706-c4f7-4929-b19b-c27839fd04d3", "type": "concept", "title": "Platform standards and developer experience"}, {"id": "4c86fa54-7d2a-45b4-9b7e-2f60305d12cb", "type": "concept", "title": "Platform risk, lock-in, and service reliability"}], "description": "Platforms shape what the organization can build, integrate, and govern."}]}, {"id": "813315fa-f14e-4842-a610-a454fed9d43f", "type": "topic", "title": "Networks, APIs, Systems Integration, and Interoperability", "description": "Modern organizations depend on systems that talk to each other. This topic explains networks, APIs, identity, integration patterns, and data exchange.", "children": [{"id": "4f0c58a0-be7c-4b5a-a611-ba19a047e328", "type": "subtopic", "title": "Network and internet basics", "children": [{"id": "5aa72689-dade-41b2-adef-71a4408781c4", "type": "concept", "title": "LAN, WAN, VPN, DNS, HTTP, routing, and wireless basics"}, {"id": "555c848d-c715-4024-8471-f3ddf8973e12", "type": "concept", "title": "Availability, bandwidth, latency, and quality of service"}, {"id": "3a803dff-37da-4c08-87df-d263ed3472ea", "type": "concept", "title": "Remote work, branch connectivity, and edge computing"}], "description": "Students learn why connectivity, latency, and reliability matter for business systems."}, {"id": "ea354975-f025-4095-8f64-41f10ba67668", "type": "subtopic", "title": "APIs and integration patterns", "children": [{"id": "0df4bb5b-746c-4ca2-b3c8-8a9b6786c29f", "type": "concept", "title": "REST, events, webhooks, middleware, and integration platforms"}, {"id": "05c79cbb-d474-43f3-9bf6-1d51e2ae5ad3", "type": "concept", "title": "Batch versus real-time integration"}, {"id": "9357dcd7-47b9-45f9-a488-e2345692b2df", "type": "concept", "title": "Error handling, retries, versioning, and monitoring"}], "description": "Modern business processes often cross application boundaries."}, {"id": "83ccab8e-558d-452a-8ade-103151cfb62d", "type": "subtopic", "title": "Identity and interoperability", "children": [{"id": "10ece115-c67d-4f56-a1e8-3be1a8c7c912", "type": "concept", "title": "Single sign-on, MFA, roles, and access federation"}, {"id": "78c17c0e-a758-43a2-9f09-ce22170ba980", "type": "concept", "title": "Data standards, EDI, XML/JSON, and canonical models"}, {"id": "79f338cf-d544-4b5c-9105-f49a701fffb6", "type": "concept", "title": "Interoperability governance and integration testing"}], "description": "Systems integration depends on trusted identities and common standards."}]}, {"id": "40d5e3e5-fc02-4587-9828-7a6c39d391e2", "type": "topic", "title": "Cybersecurity, Privacy, Risk Management, and Resilience", "description": "Security is a managerial responsibility as much as a technical one. Students learn how to identify risks, protect assets, govern privacy, and keep operations resilient.", "children": [{"id": "685b9d0e-8924-4291-975b-06dc1ca0e6f7", "type": "subtopic", "title": "Security fundamentals", "children": [{"id": "ac1ec28c-e2fe-4a49-afc4-6c543fff612d", "type": "concept", "title": "Threats, vulnerabilities, controls, and attack surfaces"}, {"id": "7e432f66-16d3-40f0-a769-5f63076edcc7", "type": "concept", "title": "Identity, endpoint, network, application, and data security"}, {"id": "1dfb5195-6b25-449f-a53a-920d7599c610", "type": "concept", "title": "Incident response, logging, and security awareness"}], "description": "Students learn the vocabulary of protecting confidentiality, integrity, and availability."}, {"id": "d5e37845-91b4-4fc1-b7df-f55173a0c03f", "type": "subtopic", "title": "Risk frameworks and resilience", "children": [{"id": "a26af011-6ccb-4006-97f8-86758b84a772", "type": "concept", "title": "NIST Cybersecurity Framework, risk assessment, and control selection"}, {"id": "40317d24-0daf-4163-96b8-cf8a95713410", "type": "concept", "title": "Business continuity, disaster recovery, and cyber resilience"}, {"id": "b2e086ff-f6fc-48cf-bfa2-7210c77341a9", "type": "concept", "title": "Third-party risk and supply-chain security"}], "description": "The course connects security to enterprise risk management."}, {"id": "785d98a9-8ce4-45ce-ae3b-48671b8d136f", "type": "subtopic", "title": "Privacy and data protection", "children": [{"id": "2001b357-ed88-4432-9509-1fbda70c9d2c", "type": "concept", "title": "Data minimization, consent, purpose limitation, and retention"}, {"id": "25a59521-af74-40f0-90a0-e048963b8a30", "type": "concept", "title": "Privacy impact assessments and privacy-by-design"}, {"id": "90a658f0-958c-4cd5-b898-3a1bce75a310", "type": "concept", "title": "Regulatory awareness and cross-border data flows"}], "description": "Privacy governs how organizations collect, use, share, and retain personal data."}]}, {"id": "5ae6ca0c-5fdd-493e-ade3-4eca3fd6cd35", "type": "topic", "title": "IT Governance, Controls, Compliance, and Auditability", "description": "World-class MIS requires decision rights, accountability, and controls. Students learn how organizations govern technology investments, risks, policies, and audit evidence.", "children": [{"id": "3582eaee-113d-4576-b80d-ff2db9f11f59", "type": "subtopic", "title": "IT governance frameworks", "children": [{"id": "79e4abcd-cc98-4842-815b-668c9701ca0c", "type": "concept", "title": "COBIT, ITIL, governance committees, and policy structures"}, {"id": "a46cdfc3-5c01-4e2d-a749-88c435386f47", "type": "concept", "title": "IT value, risk, resources, performance, and strategic alignment"}, {"id": "21bc8dd6-cab2-4275-8525-71ac344710fb", "type": "concept", "title": "Portfolio steering and investment prioritization"}], "description": "Students learn how organizations assign decision rights and measure technology performance."}, {"id": "b5b01f56-994a-44cb-8286-cb57a6654307", "type": "subtopic", "title": "Controls and compliance", "children": [{"id": "782b17b7-2299-4db7-aafa-fe708a50cdc8", "type": "concept", "title": "General IT controls, application controls, segregation of duties"}, {"id": "11e33444-4276-47a6-b58b-45e88ab47fbb", "type": "concept", "title": "Change management, access reviews, logging, and audit trails"}, {"id": "c2973cc1-88a6-4213-ab9d-2dbb15a7a287", "type": "concept", "title": "SOX, SOC reports, COSO, and regulatory expectations"}], "description": "Information systems must produce trustworthy operations and evidence."}, {"id": "9f96e9e9-21de-4ccc-bf0e-ce7377217e46", "type": "subtopic", "title": "Auditability and monitoring", "children": [{"id": "32259688-fe89-4c61-87e2-b1833353f3a9", "type": "concept", "title": "Control testing, continuous monitoring, and exception reporting"}, {"id": "0b81dd9c-aacd-4efc-9300-e1f61b68f00a", "type": "concept", "title": "Evidence retention and traceability"}, {"id": "644fca02-6aea-4c70-bfbe-70e11ead3336", "type": "concept", "title": "Risk indicators and management dashboards"}], "description": "Managers need systems that can be inspected and improved."}]}, {"id": "79c69ac6-0bab-4818-a6b4-11b500f19ceb", "type": "topic", "title": "Systems Analysis, Requirements, and Solution Design", "description": "Good systems solve the right problem. Students learn how to elicit requirements, define scope, compare solution options, and design usable technology-enabled workflows.", "children": [{"id": "1021058d-59f6-4ea2-af90-50c8b4513b57", "type": "subtopic", "title": "Problem framing", "children": [{"id": "b69346d6-ca38-4ae7-adf7-7ea340cc6d0f", "type": "concept", "title": "Stakeholder analysis and current-state assessment"}, {"id": "7ef1f696-178f-43b5-943b-e2dd4d3dd120", "type": "concept", "title": "Pain points, constraints, risks, and success criteria"}, {"id": "79af39c0-12f2-446b-81c1-6fd3ead53062", "type": "concept", "title": "Build, buy, configure, integrate, or retire decisions"}], "description": "Students learn to separate symptoms from the actual business problem."}, {"id": "284bac8f-feec-40c9-8b5e-102dc64bec6f", "type": "subtopic", "title": "Requirements engineering", "children": [{"id": "e8d8c2d9-7b6b-410d-9b53-609285f040fa", "type": "concept", "title": "Functional and nonfunctional requirements"}, {"id": "bd760adf-be75-46f5-9a8f-17f57ef053c1", "type": "concept", "title": "User stories, use cases, acceptance criteria, and traceability"}, {"id": "c47105fb-cad7-4256-abc6-b1824fbb0cef", "type": "concept", "title": "Security, privacy, accessibility, and reporting requirements"}], "description": "Requirements translate business needs into testable system expectations."}, {"id": "0036f400-2e5b-4753-b55b-7a95c262229f", "type": "subtopic", "title": "Solution design", "children": [{"id": "38353ce9-4ab3-403c-99b5-48a2469ce28c", "type": "concept", "title": "Process and data design"}, {"id": "20183198-f849-4450-b01d-56d169be0d68", "type": "concept", "title": "UX, forms, approvals, and exception handling"}, {"id": "1e72e31f-8783-4c70-84f4-2f3721b8a0fa", "type": "concept", "title": "Prototyping, feasibility, and solution architecture basics"}], "description": "Design connects workflows, data, people, interfaces, and controls."}]}, {"id": "9cbf5d24-2920-4cff-baef-9b540774bfb2", "type": "topic", "title": "IT Project Management, Agile Delivery, and Change Management", "description": "Information systems succeed through delivery discipline and adoption. This topic covers planning, estimation, agile methods, stakeholder management, and organizational change.", "children": [{"id": "18889f44-a4f1-4e20-a70b-9911b42c7131", "type": "subtopic", "title": "Project planning and estimation", "children": [{"id": "1d1a4a2b-40eb-40ca-8f3d-a529a0c8806b", "type": "concept", "title": "Work breakdown, milestones, dependencies, and critical path awareness"}, {"id": "fa6305f2-82bb-46b2-90e6-410e58792d06", "type": "concept", "title": "Estimation, budgeting, staffing, and procurement"}, {"id": "053fc0d7-c259-4d45-87ce-543b305b8bf4", "type": "concept", "title": "Risk registers, issue logs, and status reporting"}], "description": "Students learn why scope, schedule, cost, quality, and risk must be managed together."}, {"id": "1dbcc7ae-2526-43ef-bb76-c509b504001f", "type": "subtopic", "title": "Agile and product delivery", "children": [{"id": "56d16bab-805a-4873-add7-3f3cc3ec06f2", "type": "concept", "title": "Scrum, Kanban, backlogs, sprints, demos, and retrospectives"}, {"id": "f0958bfa-e8e0-4574-a6f7-e90e64cd07c4", "type": "concept", "title": "Product ownership and prioritization"}, {"id": "5f521826-2752-4cb2-87d2-bc8238510710", "type": "concept", "title": "Waterfall, agile, hybrid, and governance fit"}], "description": "Modern MIS work often delivers value iteratively."}, {"id": "ed13ea9a-1a92-438d-93d5-6ab891117584", "type": "subtopic", "title": "Change management and adoption", "children": [{"id": "40126020-1cc4-4e84-942b-f545a98342dd", "type": "concept", "title": "Stakeholder communication and training"}, {"id": "e981b3c6-417b-445c-a9e1-3ffdada1a2a4", "type": "concept", "title": "Resistance, incentives, and behavior change"}, {"id": "9486e48d-ce0f-4ebb-b4d4-d7266c8e31f5", "type": "concept", "title": "Go-live support, adoption metrics, and benefits realization"}], "description": "A technically correct system can fail if people do not adopt it."}]}, {"id": "8feb0bac-bd50-42fd-ab11-ea8436b7c814", "type": "topic", "title": "Digital Transformation, Innovation, and Platform Business Models", "description": "Technology can reshape strategy, operations, and customer experience. Students learn how firms transform business models rather than merely digitize old routines.", "children": [{"id": "20ee3652-cb2f-4b97-b7d9-03402b759531", "type": "subtopic", "title": "Transformation strategy", "children": [{"id": "de11f8a4-5f76-44f1-b4d5-eb85ac64b32f", "type": "concept", "title": "Customer, competition, data, innovation, and value domains"}, {"id": "c3a1a2fd-8ef5-46b8-aa78-247072a79576", "type": "concept", "title": "Maturity models and transformation roadmaps"}, {"id": "258f8871-1556-4ffb-89fc-d65c672bbd7f", "type": "concept", "title": "Operating model redesign and capability building"}], "description": "Students learn how digital transformation changes operating models and value creation."}, {"id": "4244611a-eb30-4ce9-825f-3d9d234984db", "type": "subtopic", "title": "Innovation management", "children": [{"id": "388fbfdb-7071-48f5-acfa-06395e7ef83b", "type": "concept", "title": "Discovery, experimentation, MVPs, and learning metrics"}, {"id": "ab97ccae-1dc8-4bb7-bbbf-62e8693f7154", "type": "concept", "title": "Disruptive innovation and incumbent response"}, {"id": "18e76e05-92bc-4eed-82b5-67db7492bd97", "type": "concept", "title": "Ecosystems, partnerships, and open innovation"}], "description": "The course treats innovation as a disciplined portfolio of experiments."}, {"id": "836dbf23-1b13-4763-b17d-ef131df60988", "type": "subtopic", "title": "Platform economics", "children": [{"id": "5ef974b1-a964-47dc-9bb6-6e604c647701", "type": "concept", "title": "Network effects and multi-sided markets"}, {"id": "af1acff6-c54b-46a6-b9d4-3e5bcc6d909a", "type": "concept", "title": "Governance, trust, moderation, and data strategy"}, {"id": "65c49437-a275-4f23-92f4-059506f1f8e6", "type": "concept", "title": "Platform scaling, monetization, and ecosystem risk"}], "description": "Platforms show how information systems can coordinate markets and communities."}]}, {"id": "86a7f915-1744-41c4-8964-8428012aef6b", "type": "topic", "title": "Emerging Technologies: AI, Automation, IoT, and Low-Code", "description": "MIS leaders must evaluate new technologies without hype. Students learn how emerging tools affect work, data, risk, productivity, and competitive positioning.", "children": [{"id": "89115567-176c-4c1c-9960-33d4ac2c74a2", "type": "subtopic", "title": "AI and machine learning in business", "children": [{"id": "0e725c19-a473-41cc-92da-e13eb6a76c0d", "type": "concept", "title": "Predictive analytics, generative AI, recommendation, and classification"}, {"id": "84862557-a280-4435-92f0-8117fd832ddc", "type": "concept", "title": "Model lifecycle, monitoring, explainability, and bias"}, {"id": "d72d9237-8b24-4e06-8ba6-8844cdd30eca", "type": "concept", "title": "AI governance, acceptable use, and human oversight"}], "description": "Students learn where AI can improve decisions and where it creates new risks."}, {"id": "b9f2f80c-bff8-40a1-bdb6-75aeac9acf1e", "type": "subtopic", "title": "Automation and low-code", "children": [{"id": "e80ed40e-d06d-48d2-9927-a1cfcf725219", "type": "concept", "title": "RPA, workflow automation, BPM, and low-code applications"}, {"id": "1b003471-e23b-45b1-9452-ad4f0a832dd6", "type": "concept", "title": "Exception handling and control design"}, {"id": "eabc8d57-6ee7-45ec-bb19-8df56e753405", "type": "concept", "title": "Citizen development and platform governance"}], "description": "Automation is useful when processes are stable, measurable, and controlled."}, {"id": "1b8901ca-eb44-4e6a-a9e8-44bfa0ef42b3", "type": "subtopic", "title": "IoT and smart operations", "children": [{"id": "a0b5ec09-52f3-41ce-8e7a-a929154ce430", "type": "concept", "title": "Sensors, telemetry, edge computing, and digital twins"}, {"id": "e1f526ff-ea4a-4798-823d-0bdc44cb9839", "type": "concept", "title": "Predictive maintenance and asset tracking"}, {"id": "02cecaee-9679-4833-928a-0d4edc299dd8", "type": "concept", "title": "IoT security, privacy, and data volume challenges"}], "description": "Connected devices extend MIS into physical operations."}]}, {"id": "67771904-73fb-4014-b8db-4f91b61d4c93", "type": "topic", "title": "Enterprise Architecture and Technology Portfolio Management", "description": "Architecture gives organizations a map of systems, data, standards, and capabilities. Students learn how architecture supports simplification, reuse, agility, and strategic planning.", "children": [{"id": "d8b5881b-ba20-47d5-ab7b-c1e4562279ff", "type": "subtopic", "title": "Architecture views", "children": [{"id": "b926a71c-831a-4284-aeaf-0cbfda1d7c8a", "type": "concept", "title": "Capability maps, application inventories, data domains, and interfaces"}, {"id": "cf9b286e-6158-45a8-a253-10192a9e08da", "type": "concept", "title": "Current-state, target-state, and transition architecture"}, {"id": "6dc81569-3fb1-44cb-bc47-a10ffe19a9a7", "type": "concept", "title": "Standards, patterns, and technology principles"}], "description": "Students learn to map business capabilities to applications, data, technology, and security."}, {"id": "23904982-a2bd-40f1-bcbe-c745abfe805c", "type": "subtopic", "title": "Portfolio rationalization", "children": [{"id": "835678bd-49b1-477b-a11a-b060f320130a", "type": "concept", "title": "Redundant systems, lifecycle risk, and modernization priorities"}, {"id": "1bd942f1-9b74-4df0-9672-4902e5344fc3", "type": "concept", "title": "Application scoring and retirement planning"}, {"id": "f706d50d-4fc9-469b-8563-2812b633d6eb", "type": "concept", "title": "Cost, risk, value, and strategic fit"}], "description": "Architecture helps reduce complexity and technical debt."}, {"id": "baa0c7bc-3d38-4b56-b91f-71b4f42f606e", "type": "subtopic", "title": "Roadmapping", "children": [{"id": "d99bcbe4-9cd5-43d6-a1c3-fae3e24f2632", "type": "concept", "title": "Dependency mapping and release planning"}, {"id": "be63060e-1003-471a-aad1-db41ff0c4567", "type": "concept", "title": "Migration waves and capability increments"}, {"id": "240358c1-f206-48cb-bcf0-5c5e37e2bb6c", "type": "concept", "title": "Governance checkpoints and architecture review boards"}], "description": "Architecture becomes useful when it guides sequencing and investment."}]}, {"id": "f8d03ef1-2efb-4da2-a706-1e702c1eb5e1", "type": "topic", "title": "Ethics, Responsible Technology, Accessibility, and Sustainability", "description": "Information systems shape people, markets, and institutions. Students learn to evaluate fairness, privacy, accessibility, labor impacts, environmental costs, and responsible design.", "children": [{"id": "715c80f5-cd6e-4b39-a5bd-d0d9f42f3222", "type": "subtopic", "title": "Responsible data and AI", "children": [{"id": "36c05cbf-7021-4fee-b9f8-f394a07071a9", "type": "concept", "title": "Bias, discrimination, explainability, and contestability"}, {"id": "76613d66-d592-4db8-8815-b5b905b57c05", "type": "concept", "title": "Data provenance, consent, and secondary use"}, {"id": "ec6876ce-7fbd-41ff-ad37-15c7eca6607a", "type": "concept", "title": "Human-centered safeguards and escalation paths"}], "description": "Students learn to evaluate harms, fairness, and accountability before deployment."}, {"id": "9d1ef095-db66-4760-87d2-cba585d908e7", "type": "subtopic", "title": "Accessibility and inclusive design", "children": [{"id": "572116bc-5a09-4a9e-ad83-1d576124c538", "type": "concept", "title": "WCAG awareness, assistive technologies, and inclusive UX"}, {"id": "8ecb90f0-7ee1-4ba8-9a76-364030ffe8a8", "type": "concept", "title": "Language, literacy, disability, and mobile access"}, {"id": "c73986b3-ec7f-4bc5-ad2f-b37c0e764c3b", "type": "concept", "title": "Usability testing with representative users"}], "description": "Information systems should work for diverse users and contexts."}, {"id": "27cf1c22-79ec-4be7-bda5-5fc31f3ff202", "type": "subtopic", "title": "Sustainable IT", "children": [{"id": "2555c340-5fcc-430a-8996-930723805fbf", "type": "concept", "title": "Energy use, cloud carbon, device lifecycle, and e-waste"}, {"id": "70e7bb8f-806b-4c0b-9143-bbc468e1873f", "type": "concept", "title": "Green procurement and sustainable architecture"}, {"id": "10978a68-25b5-4042-b782-901fa4821d8b", "type": "concept", "title": "Labor, surveillance, and workplace impacts"}], "description": "Technology has environmental and social costs."}]}, {"id": "85e0bf56-4039-4961-ac9c-b2eae7aaeaa8", "type": "topic", "title": "Vendor, Outsourcing, SaaS, and Technology Procurement Management", "description": "Many information systems are bought, rented, integrated, or outsourced. Students learn how to evaluate vendors, contracts, service levels, costs, and lock-in.", "children": [{"id": "c14cecf9-ab8f-4c7f-8a08-b5cc3eb31d5f", "type": "subtopic", "title": "Vendor selection", "children": [{"id": "efe3400e-68f5-43c5-b796-37858d774bb9", "type": "concept", "title": "RFPs, scoring models, demos, reference checks, and pilots"}, {"id": "c6f27e3c-6321-4310-b389-3aab4b1d6231", "type": "concept", "title": "Fit-gap analysis and total cost of ownership"}, {"id": "e77b8737-1d5c-406e-8585-eeb988edc644", "type": "concept", "title": "Security, privacy, integration, and data portability review"}], "description": "Students learn how to compare technology options beyond feature checklists."}, {"id": "9321224f-13fd-45a1-b41d-d077f6fbf627", "type": "subtopic", "title": "Contracts and service management", "children": [{"id": "6e14778d-9b62-40e3-9e9a-097cd493d8da", "type": "concept", "title": "SLAs, uptime, support, incident response, and exit clauses"}, {"id": "ff9da1ba-00c2-4dc2-a72d-b25612a4afa9", "type": "concept", "title": "Licensing, usage tiers, renewal traps, and audit rights"}, {"id": "c57c6b5f-a636-495d-9461-3aa38016fdf5", "type": "concept", "title": "Vendor performance metrics and relationship management"}], "description": "Purchased systems require ongoing governance."}, {"id": "f6409851-ccfb-4bd6-882c-513d4f8fe3d6", "type": "subtopic", "title": "Outsourcing and managed services", "children": [{"id": "7746064a-99df-46be-b226-84c723bfb854", "type": "concept", "title": "Make-or-buy analysis and sourcing strategy"}, {"id": "465c6bb1-dbe3-4bb2-9ff0-de5e9b73a428", "type": "concept", "title": "Managed services, offshoring, and co-sourcing"}, {"id": "655458a9-e2a9-4645-8a53-1a28afd427c4", "type": "concept", "title": "Third-party risk, continuity, and knowledge retention"}], "description": "Outsourcing shifts responsibilities but does not remove accountability."}]}, {"id": "8b95292f-061d-42ea-ab1c-26d1dab6e8cf", "type": "topic", "title": "World-Class MIS Capstone: Digital Business Case and Implementation Roadmap", "description": "The course culminates in a professional business case. Students synthesize process, data, systems, risk, economics, governance, and change into an implementation roadmap.", "children": [{"id": "d0a67366-75ae-4c6c-8f9d-be634869b174", "type": "subtopic", "title": "Business case", "children": [{"id": "7906102e-cd2e-4700-815f-bfd4aa67b31a", "type": "concept", "title": "Problem statement, options, benefits, costs, and assumptions"}, {"id": "a1c6573e-4c65-4ac7-b2cf-d3b1cac2021e", "type": "concept", "title": "ROI, payback, NPV awareness, and intangible benefits"}, {"id": "94c9c1af-1d85-447b-9de3-d0ec4adb0e2d", "type": "concept", "title": "Risk-adjusted recommendation and executive summary"}], "description": "Students justify an MIS initiative using value, risk, feasibility, and strategic fit."}, {"id": "0d1db69c-a5d4-4701-81d3-7a78cdb9ee51", "type": "subtopic", "title": "Implementation roadmap", "children": [{"id": "13d9011b-1e8b-4d04-812a-42cc4e86ee04", "type": "concept", "title": "Milestones, dependencies, releases, and governance checkpoints"}, {"id": "a478df6d-49c3-47c6-91a4-62235d3013a0", "type": "concept", "title": "Data migration, integration, testing, training, and cutover"}, {"id": "c1bf038e-6d81-4a76-8aaf-ca738dbba260", "type": "concept", "title": "Change, communications, and adoption plan"}], "description": "The roadmap turns strategy into sequenced work."}, {"id": "27499441-8bb4-45d9-849c-c07a78f9127b", "type": "subtopic", "title": "Management dashboard and reflection", "children": [{"id": "15b6c003-b2be-4c12-a3be-7d46b28cd549", "type": "concept", "title": "KPIs, leading indicators, control metrics, and benefit tracking"}, {"id": "5925c469-e352-4474-8b28-c784bf7d9e4d", "type": "concept", "title": "Post-implementation review and lessons learned"}, {"id": "2966718b-aa20-4576-9b57-18c3f56f6adb", "type": "concept", "title": "Residual risk, ownership, and continuous improvement"}], "description": "Students close the loop by defining how success will be measured."}]}], "dbBacked": true}$misjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'management-information-systems'
